class Solution {
public:
    int garbageCollection(vector<string>& garbage, vector<int>& travel) {
        int n = garbage.size();
        int total = 0;
        int lastM = -1, lastP = -1, lastG = -1;

        for (int i = 0; i < n; i++) {
            total += (int)garbage[i].size();
            for (char c : garbage[i]) {
                if (c == 'M') lastM = i;
                else if (c == 'P') lastP = i;
                else lastG = i;
            }
        }

        for (int i = 0; i < lastM; i++) total += travel[i];
        for (int i = 0; i < lastP; i++) total += travel[i];
        for (int i = 0; i < lastG; i++) total += travel[i];

        return total;
    }
};
